<?php $user=sc_user();if(!$user){$_SESSION['sc_checkout_return']=true;echo '<section class="sc-store"><h1>Checkout</h1><p>Please log in to place your order.</p><a class="sc-buy" href="'.sc_url('signin').'">Log in</a> <a href="'.sc_url('signup').'">Create an account</a></section>';return;} $items=sc_cart();if(!$items){echo '<section class="sc-store"><h1>Your cart is empty.</h1><a class="sc-buy" href="'.sc_url('products').'">Shop products</a></section>';return;}if(empty($_SESSION['sc_order_token']))$_SESSION['sc_order_token']=bin2hex(random_bytes(32));$totals=sc_totals($items,$_POST['state']??'Odisha'); ?>
<section class="sc-store"><span class="sc-kicker">THE LAST STEP</span><h1>Make it yours.</h1><?php if($GLOBALS['sc_error']): ?><div class="alert alert-danger" role="alert"><?= sc_e($GLOBALS['sc_error']) ?></div><?php endif; ?><form method="post" class="sc-cart-layout"><?= sc_token() ?><input type="hidden" name="sc_action" value="place_order"><input type="hidden" name="order_token" value="<?= sc_e($_SESSION['sc_order_token']) ?>"><div class="sc-panel"><h2>Delivery details</h2><?php foreach(['full_name'=>'Full name','phone'=>'Mobile number','address'=>'Street address','city'=>'City','state'=>'State','pin'=>'PIN code'] as $key=>$label): ?><label><?= $label ?><input name="<?= $key ?>" value="<?= sc_e($_POST[$key]??($key==='full_name'?$user['first_name'].' '.$user['last_name']:($key==='state'?'Odisha':''))) ?>" required maxlength="<?= ['full_name'=>100,'phone'=>15,'address'=>500,'city'=>100,'state'=>80,'pin'=>6][$key] ?>" <?= $key==='phone'?'type="tel" pattern="[6-9][0-9]{9}"':($key==='pin'?'inputmode="numeric" pattern="[1-9][0-9]{5}"':'') ?>></label><?php endforeach; ?></div><input type="hidden" name="quoted_total" value="<?= $totals['total'] ?>"><aside class="sc-panel"><h2>Your order</h2><?php foreach($items as $p): ?><p><?= sc_e($p['product_name']) ?> × <?= $p['quantity'] ?> <strong><?= sc_money($p['line_cents']) ?></strong></p><?php endforeach; ?><hr><p>Items <strong><?= sc_money($totals['subtotal']) ?></strong></p><p>Tax estimate <strong><?= sc_money($totals['tax']) ?></strong></p><p>Shipping <strong>₹0.00</strong></p><p><strong>Estimated total <?= sc_money($totals['total']) ?></strong></p><small>Tax uses CGST + SGST for Odisha and the product’s IGST rate for other states. The saved order uses your submitted delivery state.</small><h3>Cash on delivery</h3><p>No online payment is collected. Payment is due on delivery.</p><button class="sc-buy" type="submit">Place order · Cash on delivery ↗</button></aside></form></section>
